script:
frappe.ui.form.on('Event', {
 refresh(frm) {
   if (frm.doc.sync_with_caldav) {
	  sync_caldav(frm);    
   }
   // Add Send Invitations button if there are participants
   if (frm.doc.event_participants && frm.doc.event_participants.length > 0 && !frm.is_new()) {
     frm.add_custom_button(__('Send Invitations'), function() {
       show_invitation_dialog(frm);
     });
   }
 },
 sync_with_caldav(frm) {
   if (frm.doc.sync_with_caldav) {
	  sync_caldav(frm);    
   }
 },
 validate(frm) {
   if (frm.doc.sync_with_caldav) {
     if (frm.doc.caldav_id_calendar === undefined) {
       msgprint(__("Please Select a CalDav Calendar"));
       frappe.validated = false;
     }       
   }     
 }
});

function sync_caldav(frm) {
  if (frappe.session.user != 'Administrator') {
    frappe.call({
      method: "pibical.pibical.custom.get_calendar",
      args: {
        nuser: frappe.session.user,
      },
      callback(r) {
        var data = r.message || [];
        var options = [];
        if (data.length > 0) {
          for (var i = 0; i < data.length; i++) {
            options.push({
              'label': data[i].name,
              'value': data[i].url
            });
	      }
        }     
        frm.set_df_property("caldav_id_calendar", "options", options);
        // Only suggest a calendar when none is chosen: overwriting it made
        // before_save move the event to another calendar with a new UID
        if (!frm.doc.caldav_id_calendar && options.length > 0) {
          frm.set_value("caldav_id_calendar", options[options.length-1].value);
        }
        frm.refresh_field("caldav_id_calendar");
      }
    });
  }      
}

function show_invitation_dialog(frm) {
  // Prepare participants data for the dialog - only Contacts
  let participants_data = [];
  frm.doc.event_participants.forEach(function(participant) {
    if (participant.reference_doctype === 'Contact' && participant.reference_docname) {
      // Get contact email
      frappe.db.get_value('Contact', participant.reference_docname, 'email_id', function(r) {
        if (r && r.email_id) {
          participants_data.push({
            'participant': participant.reference_docname,
            'email': r.email_id,
            'reference_doctype': participant.reference_doctype,
            'reference_docname': participant.reference_docname,
            'send_invitation': 1
          });
        }
      });
    }
  });

  // Wait a bit for async calls to complete
  setTimeout(function() {
    if (participants_data.length === 0) {
      frappe.msgprint(__('No Contact participants with email addresses found.'));
      return;
    }

  // Create dialog
  let d = new frappe.ui.Dialog({
    title: __('Send Event Invitations'),
    fields: [
      {
        fieldname: 'participants_table',
        fieldtype: 'Table',
        label: __('Select Recipients'),
        cannot_add_rows: true,
        cannot_delete_rows: true,
        in_place_edit: true,
        data: participants_data,
        fields: [
          {
            fieldname: 'participant',
            fieldtype: 'Data',
            label: __('Participant'),
            in_list_view: 1,
            read_only: 1
          },
          {
            fieldname: 'email',
            fieldtype: 'Data',
            label: __('Email'),
            in_list_view: 1,
            read_only: 1
          },
          {
            fieldname: 'send_invitation',
            fieldtype: 'Check',
            label: __('Send Invitation'),
            in_list_view: 1,
            default: 1
          }
        ]
      }
    ],
    primary_action_label: __('Send Invitations'),
    primary_action(values) {
      let selected_recipients = values.participants_table.filter(p => p.send_invitation);

      if (selected_recipients.length === 0) {
        frappe.msgprint(__('Please select at least one recipient.'));
        return;
      }

      frappe.call({
        method: 'pibical.pibical.custom.send_event_invitations',
        args: {
          event_name: frm.doc.name,
          recipients: selected_recipients
        },
        callback: function(r) {
          if (r.message) {
            frappe.msgprint(__('Successfully sent {0} out of {1} invitations.', 
              [r.message.sent_count, r.message.total_selected]));
            d.hide();
          }
        }
      });
    }
  });

  d.show();
  }, 500); // Wait 500ms for async calls
}
